/** Breadcrumb path; past four levels the middle collapses into a menu. */
export function Crumbs({
  path,
  rootLabel,
  onGo,
}: {
  path: { id: string; name: string }[]
  rootLabel: string
  onGo: (id: string) => void
}) {
  const crumbs = [{ id: ROOT_ID, name: rootLabel }, ...path]
  const collapsed = crumbs.length > 4
  const shown = collapsed ? [crumbs[0], ...crumbs.slice(-2)] : crumbs
  const hidden = collapsed ? crumbs.slice(1, -2) : []
  return (
    <Breadcrumb className="order-last w-full min-w-0 @xl/files:order-none @xl/files:w-auto @xl/files:flex-1">
      <BreadcrumbList className="flex-nowrap overflow-hidden">
        {shown.map((c, i) => (
          <React.Fragment key={c.id}>
            {i > 0 && <BreadcrumbSeparator />}
            {collapsed && i === 1 && (
              <>
                <BreadcrumbItem>
                  <DropdownMenu>
                    <DropdownMenuTrigger
                      render={
                        <Button
                          variant="ghost"
                          size="xs"
                          aria-label={`Show ${plural(hidden.length, "hidden folder")}`}
                        />
                      }
                    >
                      …
                    </DropdownMenuTrigger>
                    <DropdownMenuContent align="start">
                      {hidden.map((h) => (
                        <DropdownMenuItem key={h.id} onClick={() => onGo(h.id)}>
                          <span className="truncate" title={h.name}>
                            {h.name}
                          </span>
                        </DropdownMenuItem>
                      ))}
                    </DropdownMenuContent>
                  </DropdownMenu>
                </BreadcrumbItem>
                <BreadcrumbSeparator />
              </>
            )}
            <BreadcrumbItem className="min-w-0">
              {i === shown.length - 1 ? (
                <BreadcrumbPage
                  title={c.name}
                  className="block max-w-40 truncate sm:max-w-64"
                >
                  {c.name}
                </BreadcrumbPage>
              ) : (
                <BreadcrumbLink
                  title={c.name}
                  render={<button type="button" onClick={() => onGo(c.id)} />}
                  className="block max-w-32 truncate sm:max-w-48"
                >
                  {c.name}
                </BreadcrumbLink>
              )}
            </BreadcrumbItem>
          </React.Fragment>
        ))}
      </BreadcrumbList>
    </Breadcrumb>
  )
}

/** Bulk actions while something is selected; item count and sort otherwise. */
export function Toolbar({
  selected,
  itemCount,
  view,
  sort,
  dir,
  onDownload,
  onMove,
  onDelete,
  onClear,
  onSortChange,
  onToggleDir,
  onViewChange,
}: {
  selected: FileEntry[]
  itemCount: number
  view: "grid" | "list"
  sort: string
  dir: "asc" | "desc"
  onDownload: (entries: FileEntry[]) => void
  onMove: (entries: FileEntry[]) => void
  onDelete: (entries: FileEntry[]) => void
  onClear: () => void
  onSortChange: (sort: string | null) => void
  onToggleDir: () => void
  onViewChange: (view: string | null) => void
}) {
  return (
    <div className="flex flex-wrap items-center gap-2 border-b px-4 pb-2">
      {selected.length > 0 ? (
        <>
          <p role="status" className="me-auto text-sm font-medium tabular-nums">
            {selected.length} selected
          </p>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => onDownload(selected)}
          >
            <DownloadIcon data-icon="inline-start" />
            Download
          </Button>
          <Button variant="ghost" size="sm" onClick={() => onMove(selected)}>
            <FolderInputIcon data-icon="inline-start" />
            Move
          </Button>
          <Button
            variant="ghost"
            size="sm"
            className="text-destructive"
            onClick={() => onDelete(selected)}
          >
            <Trash2Icon data-icon="inline-start" />
            Delete
          </Button>
          <Button
            variant="ghost"
            size="icon-sm"
            aria-label="Clear selection"
            onClick={onClear}
          >
            <XIcon />
          </Button>
        </>
      ) : (
        <>
          <p className="me-auto min-w-0 truncate text-sm text-muted-foreground tabular-nums">
            {plural(itemCount, "item")}
          </p>
          {view === "grid" && (
            <>
              {/* Fixed width: on touch the native picker replaces the trigger
                  after hydration, and must take the same space (no shift). */}
              <div className="w-32 shrink-0">
                <Select
                  items={SORTS}
                  // Names the native picker on touch, where the trigger isn't rendered.
                  aria-label="Sort by"
                  value={sort}
                  onValueChange={(v) =>
                    v && onSortChange(String(v) === "name" ? null : String(v))
                  }
                >
                  <SelectTrigger aria-label="Sort by" className="w-full">
                    <SelectValue />
                  </SelectTrigger>
                  <SelectContent>
                    {SORTS.map((s) => (
                      <SelectItem key={s.value} value={s.value}>
                        {s.label}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <Button
                variant="outline"
                size="icon"
                aria-label={
                  dir === "asc"
                    ? "Ascending, switch to descending"
                    : "Descending, switch to ascending"
                }
                onClick={onToggleDir}
              >
                {dir === "asc" ? <ArrowUpIcon /> : <ArrowDownIcon />}
              </Button>
            </>
          )}
        </>
      )}
      <ToggleGroup
        value={[view]}
        onValueChange={(v) =>
          v[0] && onViewChange(v[0] === "grid" ? null : v[0])
        }
        aria-label="View"
      >
        <ToggleGroupItem value="grid" aria-label="Grid view">
          <LayoutGridIcon />
        </ToggleGroupItem>
        <ToggleGroupItem value="list" aria-label="List view">
          <ListIcon />
        </ToggleGroupItem>
      </ToggleGroup>
    </div>
  )
}

