export function PathBar({
  path,
  rootLabel,
  onGo,
  onShowFolders,
  onUpload,
}: {
  path: { id: string; name: string }[]
  rootLabel: string
  onGo: (id: string) => void
  onShowFolders: () => void
  onUpload: () => void
}) {
  return (
    <div className="flex flex-wrap items-center gap-2 px-4 pt-3 pb-2">
      <Button
        variant="outline"
        size="icon"
        aria-label="Show folders"
        className="@3xl/files:hidden"
        onClick={onShowFolders}
      >
        <FolderTreeIcon />
      </Button>
      <Crumbs path={path} rootLabel={rootLabel} onGo={onGo} />
      <Button className="ms-auto @xl/files:ms-0" onClick={onUpload}>
        <UploadIcon data-icon="inline-start" />
        Upload
      </Button>
    </div>
  )
}

/** The folder tree as a sheet, for widths where the sidebar is hidden. */
export function FolderSheet({
  open,
  onOpenChange,
  children,
}: {
  open: boolean
  onOpenChange: (open: boolean) => void
  children: React.ReactNode
}) {
  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent side="inline-start" className="gap-0 p-0">
        <SheetHeader className="border-b p-4">
          <SheetTitle>Folders</SheetTitle>
          <SheetDescription className="sr-only">
            Pick a folder to open
          </SheetDescription>
        </SheetHeader>
        {children}
      </SheetContent>
    </Sheet>
  )
}

