export type { FileEntry } from "./file-utils"

export type UploadFn = (
  file: File,
  onProgress: (percent: number) => void,
  signal: AbortSignal
) => Promise<void>

/** Demo uploader: climbs to 100% in about two seconds; names containing "error" fail. */
export const simulateUpload: UploadFn = (file, onProgress, signal) =>
  new Promise((resolve, reject) => {
    let percent = 0
    const tick = () => {
      if (signal.aborted) return reject(new Error("Cancelled"))
      percent = Math.min(100, percent + 6 + Math.round(Math.random() * 12))
      onProgress(percent)
      if (/error/i.test(file.name) && percent > 40)
        return reject(new Error("The connection dropped. Try again."))
      if (percent >= 100) return resolve()
      setTimeout(tick, 140)
    }
    setTimeout(tick, 140)
  })

const NO_ENTRIES: FileEntry[] = []

export type FileManagerProps = {
  /** The files, when the parent owns them. Pair with `onFilesChange`. */
  files?: FileEntry[]
  /** The files to start with when `files` is left out. */
  defaultFiles?: FileEntry[]
  /** Called with the next list after every rename, move, delete or upload. */
  onFilesChange?: (files: FileEntry[]) => void
  /** Bytes the plan allows. */
  storageTotal: number
  /** Bytes used by things outside `files` (backups, other drives). */
  storageOther?: number
  rootLabel?: string
  /** The folder to show when the URL has none. */
  initialFolder?: string
  upload?: UploadFn
  onRename?: (entry: FileEntry, name: string) => void | Promise<void>
  onMove?: (entries: FileEntry[], to: string | null) => void | Promise<void>
  onDelete?: (entries: FileEntry[]) => void | Promise<void>
  onDownload?: (entries: FileEntry[]) => void
  onOpenFile?: (entry: FileEntry) => void
  onUploaded?: (entry: FileEntry) => void
  className?: string
}

/**
 * A file browser: folder tree, breadcrumb path, grid and list views, multi
 * select (click, Shift, Ctrl/Cmd, or the keyboard), a context menu (open,
 * rename, move, download, delete), uploads with progress and a storage meter.
 * Folder, view and sort live in the URL (`?folder=&view=&sort=&dir=`). Below
 * the `3xl` container width the tree moves into a sheet.
 *
 * It keeps its own copy of the files (seeded from `defaultFiles`, or driven by
 * `files` + `onFilesChange`) and reports every change through the callbacks; a
 * callback that throws or rejects rolls that change back.
 */
export function FileManager({
  files,
  defaultFiles = NO_ENTRIES,
  onFilesChange,
  storageTotal,
  storageOther = 0,
  rootLabel = "My files",
  initialFolder,
  upload = simulateUpload,
  onRename,
  onMove,
  onDelete,
  onDownload,
  onOpenFile,
  onUploaded,
  className,
}: FileManagerProps) {
  const baseId = React.useId()
  const rootRef = React.useRef<HTMLDivElement>(null)
  // The button that opened a dialog is gone once the selection clears, so the
  // keyboard goes back to the list after a move or delete.
  const focusList = () =>
    setTimeout(
      () =>
        rootRef.current
          ?.querySelector<HTMLElement>("[role=listbox]")
          ?.focus({ preventScroll: true }),
      60
    )
  const touch = useIsTouch()
  const [entries, setEntries] = useControllableState({
    value: files,
    defaultValue: defaultFiles,
    onChange: onFilesChange,
  })
  const index = React.useMemo(() => indexEntries(entries), [entries])

  const {
    folderId,
    setFolder,
    view,
    setView,
    sort,
    setSortParam,
    dir,
    toggleDir,
    handleSort,
  } = useFolderParams(index, initialFolder)

  const path = React.useMemo(
    () => (folderId === ROOT_ID ? [] : pathTo(index, folderId)),
    [index, folderId]
  )
  const items = React.useMemo(
    () => sortEntries(index.children.get(folderId) ?? [], sort, dir),
    [index, folderId, sort, dir]
  )
  const folderName = path.at(-1)?.name ?? rootLabel

  const [expanded, setExpanded] = useExpandedFolders(
    folderId,
    path.slice(0, -1).map((e) => e.id)
  )
  const nodes = React.useMemo(
    () => folderTree(index, rootLabel),
    [index, rootLabel]
  )

  const { sel, setSel, activeId, selectedEntries } = useFolderSelection(
    folderId,
    index,
    items
  )

  const [renamingId, setRenamingId] = React.useState<string | null>(null)
  const [treeOpen, setTreeOpen] = React.useState(false)
  const [uploadOpen, setUploadOpen] = React.useState(false)
  const [deleting, setDeleting] = React.useState<FileEntry[] | null>(null)
  const [moving, setMoving] = React.useState<FileEntry[] | null>(null)
  const [moveTo, setMoveTo] = React.useState<string>(ROOT_ID)
  const [announce, setAnnounce] = React.useState("")

  const used = React.useMemo(
    () => entries.reduce((sum, e) => sum + (e.size ?? 0), storageOther),
    [entries, storageOther]
  )
  const ratio = storageTotal ? used / storageTotal : 0
  const tone = ratio > 0.9 ? "red" : ratio > 0.7 ? "amber" : "green"

  const parentOf = (id: string) => (id === ROOT_ID ? null : id)

  const go = (id: string) => {
    setFolder(id)
    setTreeOpen(false)
    setRenamingId(null)
    const count = index.children.get(id)?.length ?? 0
    setAnnounce(
      `${id === ROOT_ID ? rootLabel : (index.byId.get(id)?.name ?? "Folder")}, ${plural(count, "item")}`
    )
  }

  const open = (entry: FileEntry) => {
    if (entry.type === "folder") go(entry.id)
    else if (onOpenFile) onOpenFile(entry)
    else
      toast(`Opening “${entry.name}”`, {
        description: "Hook up onOpenFile to preview it.",
      })
  }

  const { menuTargets, onContextItem } = useContextTargets(
    sel,
    setSel,
    selectedEntries
  )

  const startRename = (entry: FileEntry) => {
    setSel({ ids: new Set([entry.id]), anchor: entry.id, active: entry.id })
    setRenamingId(entry.id)
  }

  const { validateName, rename, remove, move, download } = useEntryActions({
    index,
    rootLabel,
    setEntries,
    onRename,
    onMove,
    onDelete,
    onDownload,
    onRenamed: () => setRenamingId(null),
    onRemoved: () => {
      setSel({ ids: NO_IDS, anchor: null, active: null })
      setDeleting(null)
      focusList()
    },
    onMoved: () => {
      setSel({ ids: NO_IDS, anchor: null, active: null })
      setMoving(null)
      focusList()
    },
  })

  const openMove = (list: FileEntry[]) => {
    setMoveTo(folderId)
    setMoving(list)
  }

  const { uploads, startUploads } = useUploads({
    upload,
    parentId: parentOf(folderId),
    onAdded: (entry) => setEntries((prev) => [...prev, entry]),
    onUploaded,
  })

  const { onItemClick, onKey } = useListHandlers({
    items,
    sel,
    setSel,
    activeId,
    selectedEntries,
    renamingId,
    touch,
    path,
    stopRenaming: () => setRenamingId(null),
    open,
    go,
    startRename,
    askDelete: setDeleting,
  })

  const sidebar = (
    <Sidebar
      nodes={nodes}
      value={folderId}
      expanded={expanded}
      onExpandedChange={setExpanded}
      onSelect={go}
      used={used}
      total={storageTotal}
      tone={tone}
    />
  )

  return (
    <div
      ref={rootRef}
      data-slot="file-manager"
      className={cn(
        "@container/files flex h-full min-h-0 overflow-hidden bg-background",
        className
      )}
    >
      <aside
        aria-label="Folders"
        className="hidden w-64 shrink-0 flex-col border-e @3xl/files:flex"
      >
        {sidebar}
      </aside>

      <FolderSheet open={treeOpen} onOpenChange={setTreeOpen}>
        {sidebar}
      </FolderSheet>

      <section aria-label="Files" className="flex min-w-0 flex-1 flex-col">
        <PathBar
          path={path}
          rootLabel={rootLabel}
          onGo={go}
          onShowFolders={() => setTreeOpen(true)}
          onUpload={() => setUploadOpen(true)}
        />

        <Toolbar
          selected={selectedEntries}
          itemCount={items.length}
          view={view}
          sort={sort}
          dir={dir}
          onDownload={download}
          onMove={openMove}
          onDelete={setDeleting}
          onClear={() => setSel({ ids: NO_IDS, anchor: null })}
          onSortChange={setSortParam}
          onToggleDir={toggleDir}
          onViewChange={setView}
        />

        {items.length === 0 ? (
          <EmptyFolder
            folderName={folderName}
            onUpload={() => setUploadOpen(true)}
          />
        ) : (
          <FileList
            // A new view or folder starts at the top with fresh measurements.
            key={`${view}-${folderId}`}
            items={items}
            view={view}
            baseId={baseId}
            selected={sel.ids}
            activeId={activeId}
            renamingId={renamingId}
            childCount={(id) => index.children.get(id)?.length ?? 0}
            sort={sort}
            dir={dir}
            onSort={handleSort}
            onItemClick={onItemClick}
            onItemOpen={open}
            onContextItem={onContextItem}
            onKey={onKey}
            onRenamed={rename}
            onRenameCancel={() => setRenamingId(null)}
            validateName={validateName}
            label={`Contents of ${folderName}`}
            menu={
              <ItemMenu
                targets={menuTargets}
                onUpload={() => setUploadOpen(true)}
                onOpen={open}
                onRename={startRename}
                onMove={openMove}
                onDownload={download}
                onDelete={setDeleting}
              />
            }
          />
        )}
        <p role="status" className="sr-only">
          {announce}
        </p>
      </section>

      <UploadDialog
        open={uploadOpen}
        onOpenChange={setUploadOpen}
        folderName={folderName}
        uploads={uploads}
        onFiles={startUploads}
      />

      <DeleteDialog
        entries={deleting}
        onClose={() => setDeleting(null)}
        onConfirm={remove}
      />

      <MoveDialog
        entries={moving}
        index={index}
        rootLabel={rootLabel}
        value={moveTo}
        onValueChange={setMoveTo}
        current={folderId}
        onClose={() => setMoving(null)}
        onMove={move}
      />
    </div>
  )
}

import * as React from "react"
import {
  FileArchiveIcon,
  FileCodeIcon,
  FileIcon,
  FileSpreadsheetIcon,
  FileTextIcon,
  FolderIcon,
  ImageIcon,
  MusicIcon,
  PresentationIcon,
  VideoIcon,
} from "lucide-react"

import type { TreeNode } from "@/components/ui/tree"
import type { iconTileVariants } from "@/components/ui/icon-tile"
import type { VariantProps } from "class-variance-authority"

export const ROOT_ID = "root"

export type FileEntry = {
  id: string
  name: string
  /** `null` for the top level. */
  parentId: string | null
  type: "folder" | "file"
  /** Bytes; folders have none. */
  size?: number
  /** ISO date. */
  modified: string
}

export type SortKey = "name" | "modified" | "size"
export type SortDir = "asc" | "desc"

type Tone = VariantProps<typeof iconTileVariants>["tone"]

const BY_EXT: Record<string, [React.ReactElement, Tone, string]> = {}
function register(
  exts: string,
  icon: React.ReactElement,
  tone: Tone,
  label: string
) {
  for (const ext of exts.split(" ")) BY_EXT[ext] = [icon, tone, label]
}
register(
  "png jpg jpeg gif webp svg heic avif",
  <ImageIcon />,
  "purple",
  "Image"
)
register("mp4 mov webm mkv avi", <VideoIcon />, "red", "Video")
register("mp3 wav flac ogg m4a", <MusicIcon />, "orange", "Audio")
register("pdf doc docx txt md rtf odt", <FileTextIcon />, "blue", "Document")
register("xls xlsx csv ods", <FileSpreadsheetIcon />, "green", "Spreadsheet")
register("ppt pptx key", <PresentationIcon />, "amber", "Presentation")
register("zip rar 7z tar gz", <FileArchiveIcon />, "gray", "Archive")
register("ts tsx js json html css py sh", <FileCodeIcon />, "gray", "Code")

/** Icon, tone and a spoken kind for an entry, from its type and extension. */
export function describe(entry: Pick<FileEntry, "name" | "type">) {
  if (entry.type === "folder")
    return { icon: <FolderIcon />, tone: "amber" as Tone, kind: "Folder" }
  const ext = entry.name.split(".").pop()?.toLowerCase() ?? ""
  const hit = BY_EXT[ext]
  return hit
    ? { icon: hit[0], tone: hit[1], kind: hit[2] }
    : { icon: <FileIcon />, tone: "neutral" as Tone, kind: "File" }
}

export function formatBytes(bytes: number) {
  if (bytes < 1024) return `${bytes} B`
  const units = ["KB", "MB", "GB", "TB"]
  let value = bytes / 1024
  let unit = 0
  while (value >= 1024 && unit < units.length - 1) {
    value /= 1024
    unit++
  }
  return `${value.toFixed(value < 10 ? 1 : 0)} ${units[unit]}`
}

// Fixed locale and zone, so server and browser render the same text.
const DATE = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  year: "numeric",
  timeZone: "UTC",
})
export const formatDate = (iso: string) => DATE.format(new Date(iso))

const COLLATOR = new Intl.Collator("pt-BR", {
  numeric: true,
  sensitivity: "base",
})

/** Folders first, then by `key`; ties fall back to the name. */
export function sortEntries(
  entries: FileEntry[],
  key: SortKey,
  dir: SortDir
): FileEntry[] {
  const sign = dir === "asc" ? 1 : -1
  return [...entries].sort((a, b) => {
    if (a.type !== b.type) return a.type === "folder" ? -1 : 1
    let diff = 0
    if (key === "modified") diff = a.modified.localeCompare(b.modified)
    else if (key === "size") diff = (a.size ?? 0) - (b.size ?? 0)
    return diff
      ? diff * sign
      : COLLATOR.compare(a.name, b.name) * (key === "name" ? sign : 1)
  })
}

export type FileIndex = {
  byId: Map<string, FileEntry>
  children: Map<string, FileEntry[]>
}

export function indexEntries(entries: FileEntry[]): FileIndex {
  const byId = new Map<string, FileEntry>()
  const children = new Map<string, FileEntry[]>()
  for (const e of entries) {
    byId.set(e.id, e)
    const key = e.parentId ?? ROOT_ID
    const list = children.get(key)
    if (list) list.push(e)
    else children.set(key, [e])
  }
  return { byId, children }
}

/** Folder ids from the top level down to (and including) `id`. */
export function pathTo(index: FileIndex, id: string) {
  const path: FileEntry[] = []
  let at = index.byId.get(id)
  // The bound guards a corrupt cycle.
  for (let i = 0; at && i < 100; i++) {
    path.unshift(at)
    at = at.parentId ? index.byId.get(at.parentId) : undefined
  }
  return path
}

/** Every id under `id`, `id` included. */
export function subtreeIds(index: FileIndex, id: string) {
  const out = new Set<string>()
  const stack = [id]
  while (stack.length) {
    const next = stack.pop()!
    if (out.has(next)) continue
    out.add(next)
    for (const c of index.children.get(next) ?? []) stack.push(c.id)
  }
  return out
}

/** Folders only, as tree nodes under a root node. `exclude` hides folders (and what's under them). */
export function folderTree(
  index: FileIndex,
  rootLabel: string,
  exclude?: Set<string>
): TreeNode[] {
  const build = (parent: string): TreeNode[] =>
    (index.children.get(parent) ?? [])
      .filter((e) => e.type === "folder" && !exclude?.has(e.id))
      .sort((a, b) => COLLATOR.compare(a.name, b.name))
      .map((e) => {
        const kids = build(e.id)
        return {
          id: e.id,
          label: e.name,
          icon: <FolderIcon />,
          children: kids.length ? kids : undefined,
        }
      })
  const kids = build(ROOT_ID)
  return [
    {
      id: ROOT_ID,
      label: rootLabel,
      icon: <FolderIcon />,
      children: kids.length ? kids : undefined,
    },
  ]
}
